<div class="section-intro"><div><h2>Laporan biaya operasional</h2><p>Lihat jumlah pengeluaran usaha berdasarkan rentang tanggal yang dipilih.</p></div><a class="button button-outline" href="?page=dashboard">← Dashboard</a></div>
<form class="filter-bar" method="get"><input type="hidden" name="page" value="reports"><label>Dari tanggal<input type="date" name="from" value="<?= e($from) ?>" required></label><label>Sampai tanggal<input type="date" name="to" value="<?= e($to) ?>" required></label><button class="button button-outline" type="submit">Tampilkan laporan</button></form>
<section class="stats-grid report-stats">
    <article class="stat-card"><span class="stat-icon red">−</span><span class="stat-label">Total biaya aktif</span><strong><?= rupiah($summary['total']) ?></strong><small><?= e(format_date($from)) ?> – <?= e(format_date($to)) ?></small></article>
    <article class="stat-card"><span class="stat-icon blue">▤</span><span class="stat-label">Jumlah catatan biaya</span><strong><?= number_format((int) $summary['count'], 0, ',', '.') ?></strong><small>Biaya yang belum dibatalkan</small></article>
</section>
<section class="panel table-panel"><div class="panel-heading"><div><h3>Pengeluaran per hari</h3><p>Hanya biaya aktif pada periode yang dipilih.</p></div></div>
    <?php if (!$daily_expenses): ?><div class="empty-state">Belum ada biaya aktif pada rentang tanggal ini.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Jumlah catatan</th><th>Total biaya</th></tr></thead><tbody><?php foreach ($daily_expenses as $day): ?><tr><td class="strong"><?= e(format_date($day['day'])) ?></td><td><?= number_format((int) $day['count'], 0, ',', '.') ?></td><td><?= rupiah($day['total']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
</section>
<section class="panel table-panel"><div class="panel-heading"><div><h3>Rincian biaya operasional</h3><p>Biaya yang dibatalkan tetap terlihat untuk menjaga histori, tetapi tidak dihitung sebagai biaya aktif.</p></div><a class="text-link" href="?page=expenses">Kelola biaya →</a></div>
    <?php if (!$expenses): ?><div class="empty-compact">Tidak ada biaya operasional pada periode ini.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Kategori</th><th>Keterangan</th><th>Metode</th><th>Dicatat oleh</th><th>Jumlah</th><th>Status</th></tr></thead><tbody><?php foreach ($expenses as $expense): ?><tr><td><?= e(format_date($expense['expense_date'])) ?></td><td><?= e($expense['category']) ?></td><td class="strong"><?= e($expense['description']) ?></td><td><?= e(strtoupper($expense['payment_method'])) ?></td><td><?= e($expense['created_by']) ?></td><td><?= rupiah($expense['amount']) ?></td><td><span class="badge <?= $expense['status'] === 'recorded' ? 'badge-green' : 'badge-gray' ?>"><?= $expense['status'] === 'recorded' ? 'Aktif' : 'Dibatalkan' ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
</section>
